INSERT INTO `recommendation_templates` (`id`, `user_id`, `recommendation_category_id`, `title`, `data`, `is_active`,
                                        `created_at`, `updated_at`, `deleted_at`)
VALUES (34, 1, 31, 'सिफारिस सम्बन्धमा',
        '<p><span class=\"text-big\">पत्र संख्याः&nbsp;२०७९/०८०&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span>&nbsp;&nbsp;<br><span class=\"text-big\">चलानी नं.&nbsp; :&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;लुम्बिनी प्रदेश,&nbsp;नेपाल</span></p><hr><p style=\"text-align:right;\"><span class=\"text-big\">मिति:२०७9/०9/2८&nbsp; &nbsp; &nbsp; &nbsp;</span></p><p><span class=\"text-big\">श्री बाँके जिल्ला अदालत,</span></p><p><span class=\"text-big\">नेपालगंज, बाँके ।&nbsp;</span></p><p><span class=\"text-big\">&nbsp;</span></p><p style=\"text-align:center;\"><span class=\"text-big\"><strong>विषय : सिफारिस सम्बन्धमा।</strong></span></p><p style=\"text-align:center;\"><span class=\"text-big\">&nbsp;</span></p><p style=\"text-align:justify;\"><span class=\"text-big\">&nbsp;</span></p><p style=\"text-align:justify;\"><span class=\"text-big\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;उपरोक्त सम्बन्धमा जिल्ला बाँके, नेपालगंज उप-महानगरपालिका वडा नं. ८ निवासी&nbsp;<strong>……………………………..</strong>ले तहाँ अदालतको नाममा सिफारिस गरि पाउँ भनि यस वडा कार्यालयमा पेश गरेको निवेदन अनुसार बाँके जिल्ला अदालतमा&nbsp;........................मुद्दा दर्ता गर्न अदालती शुल्क राख्नु पर्ने भएकोले हाल निज .......................संग अदालती शुल्क राख्ने नगद रकम नभएको हुँदा फिराद दर्ता गर्दा लाग्ने अदालती शुल्क पछि दाखिला गर्ने गरि फिराद पत्र दर्ता गरि दिनु हुन सिफारिस साथ अनुरोध छ।</span></p><p><span class=\"text-big\">&nbsp;</span></p><p style=\"text-align:right;\"><span class=\"text-big\">&nbsp;</span></p><p style=\"text-align:right;\"><span class=\"text-big\">……………………………………………..</span></p><p style=\"text-align:right;\"><span class=\"text-big\">वडा अध्यक्ष&nbsp;</span></p>',
        1, '2023-02-14 07:19:17', '2023-02-14 10:37:36', NULL),
       (35, 1, 30, 'कार्यवाहक वडा अध्यक्ष भई कामकाज गर्ने सम्बन्धमा',
        '<p><span class=\"text-big\">पत्र संख्याः&nbsp;२०७९/०८०&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span>&nbsp;&nbsp;<br><span class=\"text-big\">चलानी नं.&nbsp; :&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;लुम्बिनी प्रदेश,&nbsp;नेपाल</span></p><hr><p style=\"text-align:right;\"><span class=\"text-big\">मिति :&nbsp;२०७९/०८/०९&nbsp;</span></p><p style=\"text-align:right;\">&nbsp;</p><p><span class=\"text-big\">श्री <strong>........................</strong>ज्यू,&nbsp;</span></p><p><span class=\"text-big\">वडा सदस्य,</span></p><p><span class=\"text-big\">वडा नं. ८,</span></p><p><span class=\"text-big\">नेपालगंज उप-महानगरपालिका।</span></p><p>&nbsp;</p><p style=\"text-align:center;\"><span class=\"text-big\">बिषय : कार्यवाहक वडा अध्यक्ष भई कामकाज गर्ने सम्बन्धमा ।</span></p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:justify;\"><span class=\"text-big\">&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;उपरोक्त सम्बन्धमा .......................... कारणले गर्दा म कार्यालयमा उपस्थित भई कामकाज गर्न असमर्थ भएको हुँदा म फर्की नआउदा सम्मको लागि तपाई <strong>श्री ...................</strong> कार्यवाहक वडा अध्यक्ष भई<strong>&nbsp;</strong>काम काज गर्नु हुन अनुरोध छ।&nbsp;</span></p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:right;\">&nbsp;</p><p style=\"text-align:right;\">&nbsp;</p><p style=\"text-align:right;\"><span class=\"text-big\">…………………………………………..</span></p><p style=\"text-align:right;\"><span class=\"text-big\">वडा अध्यक्ष&nbsp;</span></p>',
        1, '2023-02-14 07:22:43', '2023-02-14 08:48:26', NULL),
       (36, 1, 29, 'निमित्त वडा सचिव  भई कामकाज गर्ने सम्बन्धमा',
        '<p><span class=\"text-big\">पत्र संख्याः&nbsp;२०७९/०८०&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span>&nbsp;&nbsp;<br><span class=\"text-big\">चलानी नं.&nbsp; :&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;लुम्बिनी प्रदेश,&nbsp;नेपाल</span></p><hr><p style=\"text-align:right;\"><span class=\"text-big\">मिति : २०७८/०७/०३&nbsp; &nbsp;</span></p><p style=\"text-align:right;\">&nbsp;</p><p><span class=\"text-big\">श्री&nbsp;<strong>…………………</strong> ज्यू,&nbsp;</span></p><p><span class=\"text-big\">प्रशासन सहायक (पाँचौ तह),</span></p><p><span class=\"text-big\">वडा नं. ८,</span></p><p><span class=\"text-big\">नेपालगंज उप-महानगरपालिका।</span></p><p>&nbsp;</p><p style=\"text-align:center;\"><span class=\"text-big\">बिषय : निमित्त वडा सचिव&nbsp; भई कामकाज गर्ने सम्बन्धमा ।</span></p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:justify;\"><span class=\"text-big\">&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;उपरोक्त सम्बन्धमा .......................... कारणले गर्दा म कार्यालयमा उपस्थित भई कामकाज गर्न असमर्थ भएको हुँदा म फर्की नआउदा सम्मको लागि तपाई <strong>श्री ...................</strong> निमित्त वडा सचिव भई<strong>&nbsp;</strong>काम काज गर्नु हुन अनुरोध छ।&nbsp;</span></p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:right;\"><span class=\"text-big\">………………………………………</span></p><p style=\"text-align:right;\"><span class=\"text-big\">वडा सचिव&nbsp;</span></p>',
        1, '2023-02-14 07:32:56', '2023-02-14 08:49:03', NULL),
       (37, 1, 28, 'अविवाहित प्रमाणित',
        '<p><span class=\"text-big\">पत्र संख्याः&nbsp;२०७९/०८०&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span>&nbsp;&nbsp;<br><span class=\"text-big\">चलानी नं.&nbsp; :&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;लुम्बिनी प्रदेश,&nbsp;नेपाल</span></p><hr><p style=\"text-align:right;\"><span class=\"text-big\">मिति :२०७९/०६/०२ &nbsp; &nbsp; &nbsp;</span></p><p style=\"text-align:right;\">&nbsp;</p><p><span class=\"text-big\">&nbsp; &nbsp; &nbsp;<strong>श्री जो जस संग सम्बन्ध राख्दछ।&nbsp;</strong></span></p><p>&nbsp;</p><p style=\"text-align:center;\"><span class=\"text-big\"><strong>बिषय :</strong> <strong><u>अविवाहित प्रमाणित</u> ।</strong></span></p><p style=\"text-align:center;\">&nbsp;</p><p style=\"margin-left:.3in;text-align:justify;\"><span class=\"text-big\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; उपरोक्त सम्बन्धमा&nbsp;<strong>……………………….</strong>को नाती तथा&nbsp;<strong>………………….</strong> र&nbsp;<strong>………………………..&nbsp;</strong>को छोरा जिल्ला बाँके, नेपालगंज उप-महानगरपालिका वडा नं. ८ निवासी वर्ष&nbsp;………… का&nbsp;<strong>…………………..</strong> ले निज आजको मितिसम्म अविवाहित रहेको व्यहोरा प्रमाणित गरि&nbsp;पाउँ भनि यस वडा कार्यालयमा निवेदन पेश गरेकोमा सो सम्बन्धमा बुझ्दा व्यहोरा मनाशिव खुल्न आएकोले निज ...................&nbsp; आजको मितिसम्म अविवाहित रहेको व्यहोरा प्रमाणित&nbsp; गरिएको छ।</span></p><p><span class=\"text-big\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span></p><p><span class=\"text-big\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp;</span></p><p style=\"text-align:right;\"><span class=\"text-big\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span></p><p style=\"text-align:right;\"><span class=\"text-big\">…………………………………..</span></p><p style=\"text-align:right;\"><span class=\"text-big\">वडा अध्</span>यक्ष</p>',
        1, '2023-02-14 07:37:52', '2023-02-14 08:49:34', NULL),
       (38, 1, 27, 'सिफारिस सम्बन्धमा',
        '<p><span class=\"text-big\">पत्र संख्याः&nbsp;२०७९/०८०&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span>&nbsp;&nbsp;<br><span class=\"text-big\">चलानी नं.&nbsp; :&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; लुम्बिनी प्रदेश,&nbsp;नेपाल</span></p><hr><p style=\"text-align:right;\"><span class=\"text-big\">मिति:२०७९/०४/०१ &nbsp; &nbsp;&nbsp;</span></p><p><span class=\"text-big\">श्री जो जस संग सम्बन्ध राख्दछ।&nbsp;</span></p><p>&nbsp;</p><p>&nbsp;</p><p style=\"text-align:center;\"><span class=\"text-big\">विषय :&nbsp;सिफारिस सम्बन्धमा ।</span></p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:justify;\"><span class=\"text-big\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;उपरोक्त सम्बन्धमा जिल्ला बाँके, नेपालगंज उप-महानगरपालिका वडा नं. ८ निवासी <strong>..........</strong>ले सिफारिस गरि पाउँ भनि यस वडा कार्यालयमा पेश गरेको&nbsp; निवेदन अनुसार&nbsp; निजको परिवारिको मासिक आम्दानी रु. ..................... (अक्षरेपी रु. ..................... मात्र) भएको व्यहोरा ........... प्रयोजनको लागि सिफारिस गरिएको छ।</span></p><p>&nbsp;</p><p style=\"text-align:right;\">&nbsp;</p><p style=\"text-align:right;\"><span class=\"text-big\">&nbsp; &nbsp;&nbsp;</span></p><p style=\"text-align:right;\"><span class=\"text-big\">………………………………………</span></p><p style=\"text-align:right;\"><span class=\"text-big\">वडा अध्यक्ष&nbsp;</span></p>',
        1, '2023-02-14 07:40:09', '2023-02-14 08:55:27', NULL),
       (39, 1, 26, 'सिफारिस सम्बन्धमा',
        '<p><span class=\"text-big\">पत्र संख्याः&nbsp;२०७९/०८०&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span>&nbsp;&nbsp;<br><span class=\"text-big\">चलानी नं.&nbsp; :&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;लुम्बिनी प्रदेश,&nbsp;नेपाल</span></p><hr><p style=\"text-align:right;\"><span class=\"text-big\">मिति: २०७९/०२/२६&nbsp;</span></p><p><span class=\"text-big\">श्री खानेपानी संस्थान,</span></p><p><span class=\"text-big\">नेपालगंज वितरण केन्द्र,</span></p><p><span class=\"text-big\">नेपालगंज, बाँके।</span></p><p><span class=\"text-big\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span></p><p style=\"text-align:center;\"><span class=\"text-big\">बिषय : सिफारिस सम्बन्धमा।</span></p><p>&nbsp;</p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\"><span class=\"text-big\">उपरोक्त सम्बन्धमा जिल्ला बाँके, नेपालगंज उ.म.न.पा. वडा नं. ८ निवासी <strong>.................</strong>ले निजको नाममा दर्ता स्रेस्ता रहेको तपशिल बमोजिको घरजग्गामा खानेपानीको पाइप जडान गराई पाउन तहाँ कार्यालयको नाममा सिफारिस गरि पाउँ भनि यस वडा कार्यालयमा निवेदन पेश गरेकोमा सो सम्बन्धमा तहाँको नियमानुसार निवेदक ................ को नाममा दर्ता स्रेस्ता रहेको तपशिल बमोजिमको घरजग्गामा खानेपानीको पाइप जडान गरिदिनु हुन&nbsp; सिफारिस साथ अनुरोध छ।</span></p><p style=\"text-align:justify;\"><span class=\"text-big\">तपशिल:</span></p><figure class=\"table\"><table><tbody><tr><td style=\"border:1.0pt solid black;padding:0in 5.4pt;vertical-align:top;width:.7in;\"><p style=\"text-align:center;\"><span class=\"text-big\">जिल्ला</span></p></td><td style=\"border-bottom-style:solid;border-color:black;border-left-style:none;border-right-style:solid;border-top-style:solid;border-width:1.0pt;padding:0in 5.4pt;vertical-align:top;width:109.2pt;\"><p style=\"text-align:center;\"><span class=\"text-big\">गा.वि.स./नगर</span></p></td><td style=\"border-bottom-style:solid;border-color:black;border-left-style:none;border-right-style:solid;border-top-style:solid;border-width:1.0pt;padding:0in 5.4pt;vertical-align:top;width:52.8pt;\"><p style=\"text-align:center;\"><span class=\"text-big\">वडा नं.</span></p></td><td style=\"border-bottom-style:solid;border-color:black;border-left-style:none;border-right-style:solid;border-top-style:solid;border-width:1.0pt;padding:0in 5.4pt;vertical-align:top;width:76.5pt;\"><p style=\"text-align:center;\"><span class=\"text-big\">नक्सा सि.नं.</span></p></td><td style=\"border-bottom-style:solid;border-color:black;border-left-style:none;border-right-style:solid;border-top-style:solid;border-width:1.0pt;padding:0in 5.4pt;vertical-align:top;width:63.0pt;\"><p style=\"text-align:center;\"><span class=\"text-big\">कि.नं.</span></p></td><td style=\"border-bottom-style:solid;border-color:black;border-left-style:none;border-right-style:solid;border-top-style:solid;border-width:1.0pt;padding:0in 5.4pt;vertical-align:top;width:103.5pt;\"><p style=\"text-align:center;\"><span class=\"text-big\">क्षेत्रफल</span></p></td></tr><tr><td style=\"border-bottom-style:solid;border-color:black;border-left-style:solid;border-right-style:solid;border-top-style:none;border-width:1.0pt;padding:0in 5.4pt;vertical-align:top;width:.7in;\"><p style=\"text-align:justify;\">&nbsp;</p></td><td style=\"border-bottom:1.0pt solid black;border-left-style:none;border-right:1.0pt solid black;border-top-style:none;padding:0in 5.4pt;vertical-align:top;width:109.2pt;\"><p style=\"text-align:justify;\">&nbsp;</p></td><td style=\"border-bottom:1.0pt solid black;border-left-style:none;border-right:1.0pt solid black;border-top-style:none;padding:0in 5.4pt;vertical-align:top;width:52.8pt;\"><p style=\"text-align:justify;\">&nbsp;</p></td><td style=\"border-bottom:1.0pt solid black;border-left-style:none;border-right:1.0pt solid black;border-top-style:none;padding:0in 5.4pt;vertical-align:top;width:76.5pt;\"><p style=\"text-align:justify;\">&nbsp;</p></td><td style=\"border-bottom:1.0pt solid black;border-left-style:none;border-right:1.0pt solid black;border-top-style:none;padding:0in 5.4pt;vertical-align:top;width:63.0pt;\"><p style=\"text-align:justify;\">&nbsp;</p></td><td style=\"border-bottom:1.0pt solid black;border-left-style:none;border-right:1.0pt solid black;border-top-style:none;padding:0in 5.4pt;vertical-align:top;width:103.5pt;\"><p style=\"text-align:justify;\">&nbsp;</p></td></tr></tbody></table></figure><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:right;\">&nbsp;</p><p style=\"text-align:right;\"><span class=\"text-big\">…………………………………….</span></p><p style=\"text-align:right;\"><span class=\"text-big\">वडा अध्यक्ष</span></p>',
        1, '2023-02-14 07:43:04', '2023-02-14 08:54:55', NULL),
       (40, 1, 25, 'नेपाल विद्युत प्राधिकरण  सिफारिस सम्बन्धमा',
