       (47, 1, 18, 'अपाङ्ग परिचय पत्र बनाउन',
        '<p><span class=\"text-big\">पत्र संख्याः&nbsp;२०७९/०८०&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span>&nbsp;&nbsp;<br><span class=\"text-big\">चलानी नं.&nbsp; :&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; लुम्बिनी प्रदेश,&nbsp;नेपाल</span></p><hr><p style=\"text-align:right;\"><span class=\"text-big\">मिति:२०७९/0८/२३ &nbsp; &nbsp;</span></p><p><span class=\"text-big\">श्री नेपालगंज उप-महानगरपालिका,</span></p><p><span class=\"text-big\">नगर कार्यपालिकाको कार्यालय,</span></p><p><span class=\"text-big\">नेपालगंज, बाँके ।</span></p><p>&nbsp;</p><p><span class=\"text-big\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span></p><p style=\"text-align:center;\"><span class=\"text-big\">बिषय : सिफारिस सम्बन्धमा ।</span></p><p style=\"text-align:center;\">&nbsp;</p><p><span class=\"text-big\">&nbsp; &nbsp;</span></p><p style=\"margin-left:.2in;text-align:justify;\"><span class=\"text-big\">उपरोक्त सम्बन्धमा जिल्ला बाँके, नेपालगंज उप-महानगरपालिका वडा नं. ८ निवासी <strong>..........</strong>लेनिजको छोरा/छोरी <strong>......................&nbsp;</strong>अपाङ्ग भएकोले अपाङ्ग परिचय पत्र बनाउनको लागि तहाँ कार्यालयको नाममा सिफारिस गरि पाउँ भनि यस वडा कार्यालयमा निवेदन पेश गरेकोमा सो सम्बन्धमा सोही व्यहोरा सिफारिस साथ अनुरोध छ ।</span></p><p style=\"margin-left:.2in;text-align:justify;\">&nbsp;</p><p style=\"margin-left:.2in;text-align:right;\">&nbsp;</p><p style=\"margin-left:.2in;text-align:right;\"><span class=\"text-big\">……………………………………..</span></p><p style=\"margin-left:.2in;text-align:right;\"><span class=\"text-big\">वडा अध्यक्ष&nbsp;</span></p>',
        1, '2023-02-14 08:59:24', '2023-02-14 08:59:24', NULL),
       (48, 1, 17, 'नाता प्रमाणित प्रमाणपत्र',
        '<p><span class=\"text-big\">पत्र संख्याः&nbsp;२०७९/०८०&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span>&nbsp;&nbsp;&nbsp;<br><span class=\"text-big\">चलानी नं.&nbsp; :&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; लुम्बिनी प्रदेश,&nbsp;नेपाल</span></p><hr><p style=\"text-align:right;\"><span class=\"text-big\">मिति:२०७९/०९/१७<strong><u>&nbsp;</u></strong></span></p><p style=\"margin-left:13.5pt;text-align:center;\"><span class=\"text-big\"><strong><u>नाता प्रमाणित प्रमाणपत्र</u></strong></span></p><p><span class=\"text-big\">श्री मन्नु कुमारी वैश्य ज्यू,&nbsp;</span></p><p><span class=\"text-big\">नेपालगंज उ.म.न.पा. – 8, बाँके।&nbsp;</span></p><p><span class=\"text-big\">&nbsp; &nbsp; &nbsp; &nbsp;</span></p><p style=\"text-align:justify;\"><span class=\"text-big\">देहायका व्यक्तिसँग देहाय बमोजिमको नाता सम्बन्ध रहेकोले सो नाता सम्बन्ध प्रमाणित गरी पाउँ भनि यस वडा कार्यालयमा मिति .............. मा दिनु भएको दरखास्त बमोजिम यस कार्यालयबाट आवश्यक जाँचबुझ गरी बुझ्दा तपाईको देहाय बमोजिमको व्यक्तिसँग देहाय बमोजिमको नाता सम्बन्ध कायम रहेको देखिएकोले नाता प्रमाणित गरि यो प्रमाणपत्र दिईएको छ।&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span></p><p>&nbsp;</p><figure class=\"table\"><table style=\";\"><tbody><tr><td style=\"border:1.0pt solid black;height:16.0pt;padding:0in 5.4pt;vertical-align:top;width:45.4pt;\"><span class=\"text-big\">क्र.सं.</span></td><td style=\"border-bottom-style:solid;border-color:black;border-left-style:none;border-right-style:solid;border-top-style:solid;border-width:1.0pt;height:16.0pt;padding:0in 5.4pt;vertical-align:top;width:320.0pt;\"><span class=\"text-big\">नाता सम्बन्ध कायम गरेको व्यक्तिको नाम</span></td><td style=\"border-bottom-style:solid;border-color:black;border-left-style:none;border-right-style:solid;border-top-style:solid;border-width:1.0pt;height:16.0pt;padding:0in 5.4pt;vertical-align:top;width:113.4pt;\"><span class=\"text-big\">नाता</span></td></tr><tr><td style=\"border-bottom-style:solid;border-color:black;border-left-style:solid;border-right-style:solid;border-top-style:none;border-width:1.0pt;height:11.65pt;padding:0in 5.4pt;vertical-align:top;width:45.4pt;\"><span class=\"text-big\">1</span></td><td style=\"border-bottom:1.0pt solid black;border-left-style:none;border-right:1.0pt solid black;border-top-style:none;height:11.65pt;padding:0in 5.4pt;vertical-align:top;width:320.0pt;\"><p style=\"text-align:justify;\"><span class=\"text-big\">स्व. ....................... – .............................</span></p></td><td style=\"border-bottom:1.0pt solid black;border-left-style:none;border-right:1.0pt solid black;border-top-style:none;height:11.65pt;padding:0in 5.4pt;vertical-align:top;width:113.4pt;\"><span class=\"text-big\">आमा – छोरा</span></td></tr><tr><td style=\"border-bottom-style:solid;border-color:black;border-left-style:solid;border-right-style:solid;border-top-style:none;border-width:1.0pt;height:11.65pt;padding:0in 5.4pt;vertical-align:top;width:45.4pt;\"><span class=\"text-big\">२</span></td><td style=\"border-bottom:1.0pt solid black;border-left-style:none;border-right:1.0pt solid black;border-top-style:none;height:11.65pt;pad