       (49, 1, 16, 'नापी कार्यालय',
        '<p><span class=\"text-big\">पत्र संख्याः&nbsp;२०७९/०८०&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span>&nbsp;&nbsp;&nbsp;<br><span class=\"text-big\">चलानी नं.&nbsp; :&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;लुम्बिनी प्रदेश,&nbsp;नेपाल</span></p><hr><p style=\"text-align:right;\"><span class=\"text-big\">मिति : २०७९/०९/२१ &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span></p><p><span class=\"text-big\">श्री नापी कार्यालय,</span></p><p><span class=\"text-big\">नेपालगंज, बाँके ।</span></p><p>&nbsp;</p><p>&nbsp;</p><p style=\"text-align:center;\"><span class=\"text-big\">विषय : सिफारिस &nbsp;सम्बन्धमा&nbsp;।</span></p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:justify;\"><span class=\"text-big\">&nbsp; &nbsp;&nbsp;&nbsp; उपरोक्त सम्बन्धमा जिल्ला बाँके, नेपालगंज उप-महानगरपालिका वडा नं. ८ निवासी&nbsp;<strong> .................</strong>ले तपशिल बमोजिमको जग्गाहरुको फिल्डबुक, प्लट रजिष्टरको उतार र ट्रेस नक्सा उपलब्ध गराई पाउन तहाँ कार्यालयको नाममा सिफारिस गरि पाउँ भनि यस वडा कार्यालयमा निवेदन पेश गरेकोमा सो सम्बन्धमा तहाँको नियमानुसार निजलाई सो जग्गाको फिल्डबुक, प्लट रजिष्टरको उतार र ट्रेस नक्सा उपलब्ध गराई दिनुहुन सिफारिस साथ अनुरोध छ ।</span></p><p style=\"text-align:justify;\"><span class=\"text-big\"><u>तपशिल</u>:</span></p><figure class=\"table\"><table style=\";\"><tbody><tr><td style=\"border:1.0pt solid black;padding:0in 5.4pt;vertical-align:top;width:78.9pt;\"><p style=\"text-align:center;\"><span class=\"text-big\">क्र.सं.</span></p></td><td style=\"border-bottom-style:solid;border-color:black;border-left-style:none;border-right-style:solid;border-top-style:solid;border-width:1.0pt;padding:0in 5.4pt;vertical-align:top;width:78.9pt;\"><p style=\"text-align:center;\"><span class=\"text-big\">जिल्ला</span></p></td><td style=\"border-bottom-style:solid;border-color:black;border-left-style:none;border-right-style:solid;border-top-style:solid;border-width:1.0pt;padding:0in 5.4pt;vertical-align:top;width:1.1in;\"><p style=\"text-align:center;\"><span class=\"text-big\">नगर</span></p></td><td style=\"border-bottom-style:solid;border-color:black;border-left-style:none;border-right-style:solid;border-top-style:solid;border-width:1.0pt;padding:0in 5.4pt;vertical-align:top;width:78.8pt;\"><p style=\"text-align:center;\"><span class=\"text-big\">वा.नं.</span></p></td><td style=\"border-bottom-style:solid;border-color:black;border-left-style:none;border-right-style:solid;border-top-style:solid;border-width:1.0pt;padding:0in 5.4pt;vertical-align:top;width:84.15pt;\"><p style=\"text-align:center;\"><span class=\"text-big\">नक्सा सि.नं.</span></p></td><td style=\"border-bottom-style:solid;border-color:black;border-left-style:none;border-right-style:solid;border-top-style:solid;border-width:1.0pt;padding:0in 5.4pt;vertical-align:top;width:78.85pt;\"><p style=\"text-align:center;\"><span class=\"text-big\">कि.नं.</span></p><p style=\"text-align:center;\">&nbsp;</p></td></tr><tr><td style=\"border-bottom-style:solid;border-color:black;border-left-style:solid;border-right-style:solid;border-top-style:none;border-width:1.0pt;padding:0in 5.4pt;vertical-align:top;width:78.9pt;\"><p style=\"text-align:center;\"><span class=\"text-big\">1</span></p></td><td style=\"border-bottom:1.0pt solid black;border-left-style:none;border-right:1.0pt solid black;border-top-style:none;padding:0in 5.4pt;vertical-align:top;width:78.9pt;\"><p style=\"text-align:center;\"><span class=\"text-big\">बाँके</span></p></td><td style=\"border-bottom:1.0pt solid black;border-left-style:none;border-right:1.0pt solid black;border-top-style:none;padding:0in 5.4pt;vertical-align:top;width:1.1in;\"><p style=\"text-align:center;\"><span class=\"text-big\">नेपालगंज</span></p></td><td style=\"border-bottom:1.0pt solid black;border-left-style:none;border-right:1.0pt solid black;border-top-style:none;padding:0in 5.4pt;vertical-align:top;width:78.8pt;\"><p style=\"text-align:center;\">&nbsp;</p></td><td style=\"border-bottom:1.0pt solid black;border-left-style:none;border-right:1.0pt solid black;border-top-style:none;padding:0in 5.4pt;vertical-align:top;width:84.15pt;\"><p style=\"text-align:center;\">&nbsp;</p></td><td style=\"border-bottom:1.0pt solid black;border-left-style:none;border-right:1.0pt solid black;border-top-style:none;padding:0in 5.4pt;vertical-align:top;width:78.85pt;\"><p style=\"text-align:center;\">&nbsp;</p></td></tr><tr><td style=\"border-bottom-style:solid;border-color:black;border-left-style:solid;border-right-style:solid;border-top-style:none;border-width:1.0pt;padding:0in 5.4pt;vertical-align:top;width:78.9pt;\"><p style=\"text-align:center;\"><span class=\"text-big\">2</span></p></td><td style=\"border-bottom:1.0pt solid black;border-left-style:none;border-right:1.0pt solid black;border-top-style:none;padding:0in 5.4pt;vertical-align:top;width:78.9pt;\"><p style=\"text-align:center;\"><span class=\"text-big\">बाँके</span></p></td><td style=\"border-bottom:1.0pt solid black;border-left-style:none;border-right:1.0pt solid black;border-top-style:none;padding:0in 5.4pt;vertical-align:top;width:1.1in;\"><p style=\"text-align:center;\"><span class=\"text-big\">नेपालगंज</span></p></td><td style=\"border-bottom:1.0pt solid black;border-left-style:none;border-right:1.0pt 