       (50, 1, 15, 'भोगचलनको सिफारिस गरि पाउँ',
        '<p><span class=\"text-big\">पत्र संख्याः&nbsp;२०७९/०८०&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span>&nbsp;&nbsp;&nbsp;<br><span class=\"text-big\">चलानी नं.&nbsp; :&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;लुम्बिनी प्रदेश,&nbsp;नेपाल</span></p><hr><p style=\"text-align:right;\"><span class=\"text-big\">मिति : २०७९/०१/20 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span></p><p><span class=\"text-big\">श्री नापी कार्यालय,</span></p><p><span class=\"text-big\">नेपालगंज, बाँके ।</span></p><p>&nbsp;</p><p>&nbsp;</p><p style=\"text-align:center;\"><span class=\"text-big\">विषय : सिफारिस &nbsp;सम्बन्धमा&nbsp;।</span></p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:justify;\"><span class=\"text-big\">उपरोक्त सम्बन्धमा जिल्ला बाँके, नेपालगंज उप-महानगरपालिका वडा नं. ८ निवासी <strong>.................</strong>ले तहाँ कार्यालयको नाममा हक भोगचलनको सिफारिस गरि पाउँ भनि यस वडा कार्यालयमा निवेदन पेश गरेकोमा सो सम्बन्धमा बुझ्दा <strong>पूर्व – .................., पश्चिम – .................., उत्तर – ............................... र दक्षिण – ...........................</strong>, यति चार किल्ला भित्र रहेको तपशिल बमोजिमको जग्गा तपशिल बमोजिमको व्यक्ति/व्यक्तिहरुको हक भोगचलनमा रहेको व्यहोरा ............ प्रयोजनको लागि सिफारिस साथ अनुरोध छ ।&nbsp;</span></p><p style=\"text-align:justify;\"><span class=\"text-big\">तपशिल:</span></p><figure class=\"table\"><table style=\";\"><tbody><tr><td style=\"border:1.0pt solid black;padding:0in 5.4pt;vertical-align:top;width:.7in;\"><p style=\"text-align:justify;\"><span class=\"text-big\">जिल्ला</span></p></td><td style=\"border-bottom-style:solid;border-color:black;border-left-style:none;border-right-style:solid;border-top-style:solid;border-width:1.0pt;padding:0in 5.4pt;vertical-align:top;width:109.2pt;\"><p style=\"text-align:justify;\"><span class=\"text-big\">गा.वि.स./नगर</span></p></td><td style=\"border-bottom-style:solid;border-color:black;border-left-style:none;border-right-style:solid;border-top-style:solid;border-width:1.0pt;padding:0in 5.4pt;vertical-align:top;width:52.8pt;\"><p style=\"text-align:justify;\"><span class=\"text-big\">वडा नं.</span></p></td><td style=\"border-bottom-style:solid;border-color:black;border-left-style:none;border-right-style:solid;border-top-style:solid;border-width:1.0pt;padding:0in 5.4pt;vertical-align:top;width:76.5pt;\"><p style=\"text-align:justify;\"><span class=\"text-big\">नक्सा सि.नं.</span></p></td><td style=\"border-bottom-style:solid;border-color:black;border-left-style:none;border-right-style:solid;border-top-style:solid;border-width:1.0pt;padding:0in 5.4pt;vertical-align:top;width:63.0pt;\"><p style=\"text-align:justify;\"><span class=\"text-big\">कि.नं.</span></p></td><td style=\"border-bottom-style:solid;border-color:black;border-left-style:none;border-right-style:solid;border-top-style:solid;border-width:1.0pt;padding:0in 5.4pt;vertical-align:top;width:103.5pt;\"><p style=\"text-align:justify;\"><span class=\"text-big\">क्षेत्रफल</span></p></td></tr><tr><td style=\"border-bottom-style:solid;border-color:black;border-left-style:solid;border-right-style:solid;border-top-style:none;border-width:1.0pt;padding:0in 5.4pt;vertical-align:top;width:.7in;\"><p style=\"text-align:justify;\">&nbsp;</p></td><td style=\"border-bottom:1.0pt solid black;border-left-style:none;border-right:1.0pt solid black;border-top-style:none;padding:0in 5.4pt;vertical-align:top;width:109.2pt;\"><p style=\"text-align:justify;\">&nbsp;</p></td><td style=\"border-bottom:1.0pt solid black;border-left-style:none;border-right:1.0pt solid black;border-top-style:none;padding:0in 5.4pt;vertical-align:top;width:52.8pt;\"><p style=\"text-align:justify;\">&nbsp;</p></td><td style=\"border-bottom:1.0pt solid black;border-left-style:none;border-right:1.0pt solid black;border-top-style:none;padding:0in 5.4pt;vertical-align:top;width:76.5pt;\"><p style=\"text-align:justify;\">&nbsp;</p></td><td style=\"border-bottom:1.0pt solid black;border-left-style:none;border-right:1.0pt solid black;border-top-style:none;padding:0in 5.4pt;vertical-align:top;width:63.0pt;\"><p style=\"text-align:justify;\">&nbsp;</p></td><td style=\"border-bottom:1.0pt solid black;border-left-style:none;border-right:1.0pt solid black;border-top-style:none;padding:0in 5.4pt;vertical-align:top;width:103.5pt;\"><p style=\"text-align:justify;\">&nbsp;</p></td></tr></tbody></table></figure><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\"><span class=\"text-big\">जग्गा हकभोगचलन गरिरहेका व्यक्ति/व्यक्तिहरुको विवरण:</span></p><p style=\"text-align:justify;\"><span class=\"text-big\">नामथर:&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; नामथर:</span></p><p style=\"text-align:justify;\"><span class=\"text-big\">ठेगाना:&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;ठेगाना:</span></p><p style=\"text-align:justify;\"><span class=\"text-big\">ना.प्र.नं.:&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ना.प्र.नं.:</span></p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\"><span class=\"text-big\">नामथर:&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;नामथर:</span></p><p style=\"text-align:justify;\"><span class=\"text-big\">ठेगाना:&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ठेगाना:</span></p><p style=\"text-align:justify;\"><span class=\"text-big\">ना.प्र.नं.:&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ना.प्र.नं.:</span></p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:right;\"><span class=\"text-big\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span></p><p style=\"text-align:right;\"><span class=\"text-big\">&nbsp;&nbsp;…………………………………….</span></p><p style=\"text-align:right;\"><span class=\"text-big\">&nbsp;वडा अध्यक्ष</span></p>',
