       (51, 1, 14, 'बिरामी भएको र निजको आर्थिक अवस्था कमजोर',
        '<p><span class=\"text-big\">पत्र संख्याः&nbsp;२०७९/०८०&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span>&nbsp;&nbsp;&nbsp;&nbsp;<br><span class=\"text-big\">चलानी नं.&nbsp; :&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;लुम्बिनी प्रदेश,&nbsp;नेपाल</span></p><hr><p style=\"text-align:right;\"><span class=\"text-big\">&nbsp;मिति: २०७९/०९/१९ &nbsp; &nbsp;&nbsp;</span></p><p><span class=\"text-big\"><strong>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</strong></span></p><p><span class=\"text-big\">श्री भेरी अस्पताल,&nbsp;</span></p><p><span class=\"text-big\">&nbsp; &nbsp; &nbsp; नेपालगंज, बाँके।</span></p><p>&nbsp;</p><p>&nbsp;</p><p style=\"text-align:center;\"><span class=\"text-big\">बिषयः सिफारिस सम्बन्धमा।</span></p><p style=\"text-align:center;\">&nbsp;</p><p>&nbsp;</p><p style=\"margin-left:.25in;text-align:justify;\"><span class=\"text-big\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; उपरोक्त सम्बन्धमा नेपालगंज उप-महानगरपालिका वडा नं ८ निवासी <strong>.....................</strong>ले निजको बाबु/आमा/छोरा/छोरी <strong>...................</strong> बिरामी भएको र निजको आर्थिक अवस्था कमजोर भएकोले आवश्यक जाँच/उपचार गराउन असमर्थ भएको हुँदा निशुल्क/सहुलियतको लागि तहाँ अस्पतालको नाममा सिफारिस गरि पाउँ भनि यस वडा कार्यालयमा निबेदन पेश गरेकोमा सो सम्बन्धमा तहाँ अस्पतालको नियमानुसार निशुल्क/सहुलियतको लागि सिफारिस साथ अनुरोध छ।</span></p><p style=\"margin-left:.25in;text-align:justify;\">&nbsp;</p><p style=\"margin-left:.25in;text-align:right;\">&nbsp;</p><p style=\"margin-left:.25in;text-align:right;\">&nbsp;</p><p style=\"margin-left:.25in;text-align:right;\"><span class=\"text-big\">……………………………………….</span></p><p style=\"margin-left:.25in;text-align:right;\"><span class=\"text-big\">वडा अध्यक्ष</span></p>',
        1, '2023-02-14 09:58:19', '2023-02-14 09:58:19', NULL),
       (52, 1, 13, 'समुदायको भएको व्यहोरा',
        '<p><span class=\"text-big\">पत्र संख्याः&nbsp;२०७९/०८०&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span>&nbsp;&nbsp;&nbsp;&nbsp;<br><span class=\"text-big\">चलानी नं.&nbsp; :&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; लुम्बिनी प्रदेश,&nbsp;नेपाल</span></p><hr><p style=\"margin-left:27.0pt;text-align:right;\"><span class=\"text-big\">&nbsp; &nbsp; मिति:२०७९/१०/०३&nbsp;</span></p><p style=\"margin-left:27.0pt;\">&nbsp;</p><p style=\"margin-left:27.0pt;\">&nbsp;</p><p>&nbsp;</p><p><span class=\"text-big\">श्री जिल्ला प्रशासन कार्यालय,</span></p><p><span class=\"text-big\">&nbsp;नेपालगंज, बाँके&nbsp;।</span></p><p>&nbsp;</p><p style=\"margin-left:27.0pt;\"><span class=\"text-big\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span></p><p style=\"text-align:center;\"><span class=\"text-big\">बिषय: सिफारिश सम्बन्धमा ।</span></p><p style=\"text-align:center;\">&nbsp;</p><p>&nbsp;</p><p><span class=\"text-big\">&nbsp; &nbsp;</span></p><p style=\"margin-left:9.0pt;text-align:justify;\"><span class=\"text-big\">उपरोक्त सम्बन्धमा <strong>.............................</strong>को छोरा/छोरी जिल्ला बाँके, नेपालगंज उप-महानगरपालिका वडा नं ८ निवासी <strong>.........................&nbsp;</strong>ले<strong>&nbsp;</strong>निज <strong>................. </strong>समुदायको भएको व्यहोरा तहाँ कार्यालयको नाममा सिफारिश गरि पाउँ भनि यस वडा कार्यालयमा निबेदन पेश गरेकोमा सो सम्बन्धमा बुझ्दा निज निवेदक <strong>..............&nbsp;</strong>समुदायको भएको व्यहोरा सिफारिश साथ अनुरोध छ&nbsp;।</span></p><p style=\"margin-left:9.0pt;\">&nbsp;</p><p style=\"margin-left:9.0pt;\">&nbsp;</p><p style=\"margin-left:9.0pt;\">&nbsp;</p><p style=\"margin-left:9.0pt;text-align:right;\">&nbsp;</p><p style=\"margin-left:9.0pt;text-align:right;\"><span class=\"text-big\">…………………………………………</span></p><p style=\"margin-left:9.0pt;text-align:right;\"><span class=\"text-big\">वडा अध्यक्ष&nbsp;</span></p>',
        1, '2023-02-14 10:00:37', '2023-02-14 10:00:37', NULL),
       (53, 1, 12, 'जग्गाधनी दर्ता प्रमाणपुर्जा हराएको हुँदा',
        '<p><span class=\"text-big\">पत्र संख्याः&nbsp;२०७९/०८०&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span>&nbsp;&nbsp;&nbsp;&nbsp;<br><span class=\"text-big\">चलानी नं.&nbsp; :&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;लुम्बिनी प्रदेश,&nbsp;नेपाल</span></p><hr><p style=\"text-align:right;\"><span class=\"text-big\">मिति:२०७९/०७/२४ &nbsp;</span></p><p style=\"text-align:right;\">&nbsp;</p><p style=\"text-align:right;\">&nbsp;</p><p><span class=\"text-big\">श्री भूमिसुधार तथा मालपोत कार्यालय,&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span></p><p><span class=\"text-big\">नेपालगन्ज, बाँके ।</span></p><p><span class=\"text-big\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span></p><p style=\"text-align:center;\"><span class=\"text-big\"><strong><u>बिषयः सिफारिस सम्बन्धमा</u>।</strong></span></p><p><span class=\"text-big\"><strong><u>&nbsp;</u></strong></span></p><p style=\"text-align:justify;\"><span class=\"text-big\">उपरोक्त सम्बन्धमा जिल्ला बाँके, नेपालगंज उ.म.न.पा. वडा नं. ८ निवासी&nbsp; <strong>................... </strong>ले निजको नाममा दर्ता श्रेस्ता रहेको जिल्ला बाँके, नेपालगंज नगर, वडा नं. ...., नक्सा सि.नं. ....................... को कि.नं. ...., क्षेत्रफल ....... व.मि.को जग्गाको जग्गाधनी दर्ता प्रमाणपुर्जा हराएको हुँदा सो जग्गाको जग्गाधनी दर्ता प्रमाणपुर्जाको प्रतिलिपि उपलब्ध गराई पाउन तहाँ कार्यालयको नाममा सिफारिस गरि पाउँ भनि यस वडा कार्यालयमा निवेदन पेश गरेकोमा सो सम्बन्धमा तहाँ कार्यालयको नियमानुसार निज <strong>.................</strong>लाई उल्लेखित जग्गाको जग्गाधनी दर्ता प्रमाणपुर्जाको प्रतिलिपि उपलब्ध गराई दिनु हुन सिफारिस साथ अनुरोध छ।</span></p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\">&nbsp;</p><p><br>&nbsp;</p><p style=\"text-align:justify;\"><span class=\"text-big\">नामथर: ........................</span></p><p style=\"text-align:justify;\"><span class=\"text-big\">बाबु/पतिको नामथर : ........................</span></p><p style=\"text-align:justify;\"><span class=\"text-big\">बाजे/ससुराको नामथर : ............................</span></p><p style=\"text-align:justify;\"><span class=\"text-big\">ना.प्र.नं. : ...................., मिति ......................, बाँके</span></p><p style=\"text-align:right;\">&nbsp;</p><p style=\"text-align:right;\">&nbsp;</p><p style=\"text-align:right;\"><span class=\"text-big\">……………………………………….</span></p><p style=\"text-align:right;\"><span class=\"text-big\">वडा अध्यक्ष</span></p>',
        1, '2023-02-14 10:07:51', '2023-02-14 10:10:25', NULL);
INSERT INTO `recommendation_templates` (`id`, `user_id`, `recommendation_category_id`, `title`, `data`, `is_active`,
