       (55, 1, 10, 'पारिवारिक विवरण सिफारिस गरि पाउँ',
        '<p><span class=\"text-big\">पत्र संख्याः&nbsp;२०७९/०८०&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span>&nbsp;&nbsp;&nbsp;&nbsp;<br><span class=\"text-big\">चलानी नं.&nbsp; :&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;लुम्बिनी प्रदेश,&nbsp;नेपाल</span></p><hr><p style=\"text-align:right;\"><span class=\"text-big\">मिति: २०७९/०३/२८&nbsp;</span></p><p><span class=\"text-big\">श्री जो जस संग सम्बन्ध राख्दछ,</span></p><p><span class=\"text-big\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span></p><p style=\"text-align:center;\"><span class=\"text-big\">बिषय: सिफारिस सम्बन्धमा।</span></p><p style=\"text-align:center;\">&nbsp;</p><p>&nbsp;</p><p style=\"text-align:justify;\"><span class=\"text-big\">उपरोक्त सम्बन्धमा जिल्ला बाँके, नेपालगंज उप-महानगरपालिका वडा नं ८&nbsp;निवासी <strong>..............</strong>ले निजको पारिवारिक विवरण सिफारिस गरि पाउँ भनि यस वडा कार्यालयमा पेश गरेकोमा सो सम्बन्धमा निजको पारिवारिक विवरण तपशिल बमोजिम रहेको व्यहोरा ........ प्रयोजनको लागि&nbsp; सिफारिस गरिएको छ।</span></p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\"><span class=\"text-big\"><u>तपशिल</u></span></p><ol><li style=\"text-align:justify;\"><span class=\"text-big\">.................. (निवेदक)&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span></li><li style=\"text-align:justify;\"><span class=\"text-big\">.................... (बाबु)</span></li><li style=\"text-align:justify;\"><span class=\"text-big\">.................... (आमा)</span></li><li style=\"text-align:justify;\"><span class=\"text-big\">................... (पत्नी)</span></li><li style=\"text-align:justify;\"><span class=\"text-big\">.................... (छोरा)</span></li><li style=\"text-align:justify;\"><span class=\"text-big\">................... (छोरी)</span></li></ol><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:right;\"><span class=\"text-big\">……………………………………….</span></p><p style=\"text-align:right;\"><span class=\"text-big\">वडा अध्यक्ष&nbsp; &nbsp; &nbsp;</span></p>',
        1, '2023-02-14 10:12:33', '2023-02-14 10:12:33', NULL),
       (56, 1, 9, 'सगोलनामा सिफारिस गरि पाउँ',
        '<p><span class=\"text-big\">पत्र संख्याः&nbsp;२०७९/०८०&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span>&nbsp;&nbsp;&nbsp;&nbsp;<br><span class=\"text-big\">चलानी नं.&nbsp; :&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;लुम्बिनी प्रदेश,&nbsp;नेपाल</span></p><hr><p style=\"text-align:right;\">&nbsp;&nbsp;<span class=\"text-big\"> &nbsp; मिति: २०७९/१०/०३&nbsp;</span></p><p><span class=\"text-big\">श्री जो जस संग सम्बन्ध राख्दछ,</span></p><p><span class=\"text-big\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span></p><p>&nbsp;</p><p style=\"text-align:center;\"><span class=\"text-big\">बिषय: सिफारिस सम्बन्धमा।</span></p><p style=\"text-align:center;\">&nbsp;</p><p>&nbsp;</p><p style=\"text-align:justify;\"><span class=\"text-big\">उपरोक्त सम्बन्धमा जिल्ला बाँके, नेपालगंज उप-महानगरपालिका वडा नं ८ निवासी <strong>................. </strong>ले सगोलनामा सिफारिस गरि पाउँ भनि यस वडा कार्यालयमा निवेदन पेश गरेकोमा सो सम्बन्धमा निज .............. तपशिल बमोजिमका परिवार सदस्य सहित आजको मिति सम्म एकासगोलमा बसोबास गरिरहेको व्यहोरा ....... प्रयोजनको लागि सिफारिस गरिएको छ।</span></p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\"><span class=\"text-big\"><u>तपशिल:&nbsp;</u></span></p><ol><li style=\"text-align:justify;\"><span class=\"text-big\">&nbsp;...............…………………………………. &nbsp;(निवेदक)&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span></li><li style=\"text-align:justify;\"><span class=\"text-big\">..................……………………………….. &nbsp;(बाबु)</span></li><li style=\"text-align:justify;\"><span class=\"text-big\">.................………………………………… &nbsp;(आमा)</span></li><li style=\"text-align:justify;\"><span class=\"text-big\">.................………………………………… &nbsp;(पत्नी)</span></li><li style=\"text-align:justify;\"><span class=\"text-big\">..................……………………………….. &nbsp;(छोरा)</span></li><li style=\"text-align:justify;\"><span class=\"text-big\">................…………………………………. &nbsp;(छोरी)</span></li></ol><p style=\"margin-left:0in;text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:right;\"><span class=\"text-big\">……………………………………………</span></p><p style=\"text-align:right;\"><span class=\"text-big\">वडा अध्यक्ष</span></p>',
