       (62, 1, 3, 'स्थायी बसोबास सिफारिस गरि पाउँ',
        '<p><span class=\"text-big\">पत्र संख्याः&nbsp;२०७९/०८०&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span>&nbsp;&nbsp;&nbsp;&nbsp;<br><span class=\"text-big\">चलानी नं.&nbsp; :&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;लुम्बिनी प्रदेश,&nbsp;नेपाल</span></p><hr><p style=\"margin-left:13.5pt;text-align:right;\"><span class=\"text-big\">मिति:२०७९/०२/२७</span></p><p style=\"margin-left:.5in;\">&nbsp;</p><p style=\"margin-left:.5in;\">&nbsp;</p><p><span class=\"text-big\">श्री जो जस संग सम्बन्ध राख्दछ।&nbsp;</span></p><p>&nbsp;</p><p style=\"margin-left:13.5pt;text-align:right;\">&nbsp;</p><p style=\"margin-left:13.5pt;text-align:center;\"><span class=\"text-big\">बिषय: सिफारिस सम्बन्धमा ।</span></p><p style=\"margin-left:13.5pt;text-align:center;\">&nbsp;</p><p style=\"margin-left:13.5pt;text-align:center;\">&nbsp;</p><p style=\"text-align:justify;\"><span class=\"text-big\">उपरोक्त सम्बन्धमा जिल्ला बाँके, नेपालगंज उ.म.न.पा. वडा नं. ८ निवासी&nbsp;<strong>..............</strong>ले स्थायी बसोबास सिफारिस गरि पाउँ भनि यस वडा कार्यालयमा निवेदन पेश गरेकोमा सो सम्बन्धमा बुझ्दा निज .............. जिल्ला बाँके, नेपालगंज उ.म.न.पा. वडा नं. ८ मा &nbsp;स्थायी रुपमा बसोबास गरिरहेको व्यहोरा सिफारिस साथ अनुरोध छ ।&nbsp;</span></p>',
        1, '2023-02-14 10:34:16', '2023-02-14 10:34:16', NULL),
       (63, 1, 1, 'हकवाला तपशिल',
        '<p><span class=\"text-big\">पत्र संख्याः&nbsp;२०७९/०८०&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span>&nbsp;&nbsp;&nbsp;&nbsp;<br><span class=\"text-big\">चलानी नं.&nbsp; :&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;लुम्बिनी प्रदेश,&nbsp;नेपाल</span></p><hr><p style=\"text-align:right;\"><span class=\"text-big\">मिति:२०७९/०९/०४&nbsp;</span></p><p style=\"text-align:right;\">&nbsp;</p><p style=\"text-align:right;\">&nbsp;</p><p><span class=\"text-big\">श्री भूमिसुधार तथा मालपोत कार्यालय,&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span></p><p><span class=\"text-big\">नेपालगन्ज, बाँके ।</span></p><p><span class=\"text-big\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span></p><p style=\"text-align:center;\"><span class=\"text-big\"><strong><u>बिषयः सिफारिश सम्बन्धमा।</u></strong></span></p><p>&nbsp;</p><p style=\"text-align:justify;\"><span class=\"text-big\">उपरोक्त सम्बन्धमा जिल्ला बाँके, नेपालगंज उ.म.न.पा. वडा नं. ८ निवासी निवेदक <strong>.................</strong>ले निजको बाबु/आमा/सासु/ससुरा <strong>................</strong>को मिति <strong>......................</strong> गते आफ्नो कालगतिले निधन भएको र निजको शेष पछि हक खाने सबैभन्दा नजिकको हकवाला तपशिल बमोजिमको व्यक्ति/व्यक्तिहरु मात्र भएको हुँदा<strong>&nbsp;</strong>मृतक <strong>.....................</strong>को नाममा दर्ता स्रेस्ता रहेको तपशिल बमोजिमको जग्गा/जग्गाहरु तपशिल बमोजिमको हकवाला/हकवालाहरु नाममा एकलौटी/संयुक्त नामसारीको लागि तहाँ कार्यालयको नाममा सिफारिश गरि पाउँ भनी यस वडा कार्यालयमा निवेदन पेश गरेकोमा सो सम्बन्धमा बुझ्दा व्यहोरा मनासिव खुल्न आएकोले तपशिलमा उल्लेखित जग्गा/जग्गाहरु तपशिल बमोजिमको हकवाला/हकवालाहरुको नाममा तहाँको नियमानुसार एकलौटी/संयुक्त नामसारीको लागि सिफारिश साथ अनुरोध छ।</span></p><p style=\"text-align:justify;\"><span class=\"text-big\"><strong>तपशिल</strong> :</span></p><figure class=\"table\"><table style=\";\"><tbody><tr><td style=\"border:1.0pt solid black;padding:0in 5.4pt;vertical-align:top;width:40.85pt;\"><p style=\"text-align:center;\"><span class=\"text-big\">क्र.सं.</span></p></td><td style=\"border-bottom-style:solid;border-color:black;border-left-style:none;border-right-style:solid;border-top-style:solid;border-width:1.0pt;padding:0in 5.4pt;vertical-align:top;width:43.4pt;\"><p style=\"text-align:center;\"><span class=\"text-big\">जिल्ला</span></p></td><td style=\"border-bottom-style:solid;border-color:black;border-left-style:none;border-right-style:solid;border-top-style:solid;border-width:1.0pt;padding:0in 5.4pt;vertical-align:top;width:72.45pt;\"><p style=\"text-align:center;\"><span class=\"text-big\">गा.वि.स./ नगर&nbsp;</span></p></td><td style=\"border-bottom-style:solid;border-color:black;border-left-style:none;border-right-style:solid;border-top-style:solid;border-width:1.0pt;padding:0in 5.4pt;vertical-align:top;width:56.35pt;\"><p style=\"text-align:center;\"><span class=\"text-big\">वडा नं.</span></p></td><td style=\"border-bottom-style:solid;border-color:black;border-left-style:none;border-right-style:solid;border-top-style:solid;border-width:1.0pt;padding:0in 5.4pt;vertical-align:top;width:62.05pt;\"><p style=\"text-align:center;\"><span class=\"text-big\">कि.नं.</span></p></td><td style=\"border-bottom-style:solid;border-color:black;border-left-style:none;border-right-style:solid;border-top-style:solid;border-width:1.0pt;padding:0in 5.4pt;vertical-align:top;width:80.65pt;\"><p style=\"text-align:center;\"><span class=\"text-big\">क्षेत्रफल</span></p></td><td style=\"border-bottom-style:solid;border-color:black;border-left-style:none;border-right-style:solid;border-top-style:solid;border-width:1.0pt;padding:0in 5.4pt;vertical-align:top;width:123.05pt;\"><p style=\"text-align:center;\"><span class=\"text-big\">दर्तावाल</span></p></td></tr><tr><td style=\"border-bottom-style:solid;border-color:black;border-left-style:solid;border-right-style:solid;border-top-style:none;border-width:1.0pt;padding:0in 5.4pt;vertical-align:top;width:40.85pt;\"><p style=\"text-align:center;\">&nbsp;</p></td><td style=\"border-bottom:1.0pt solid black;border-left-style:none;border-right:1.0pt solid black;border-top-style:none;padding:0in 5.4pt;vertical-align:top;width:43.4pt;\"><p style=\"text-align:center;\">&nbsp;</p></td><td style=\"border-bottom:1.0pt solid black;border-left-style:none;border-right:1.0pt solid black;border-top-style:none;padding:0in 5.4pt;vertical-align:top;width:72.45pt;\"><p style=\"text-align:center;\">&nbsp;</p></td><td style=\"border-bottom:1.0pt solid black;border-left-style:none;border-right:1.0pt solid black;border-top-style:none;padding:0in 5.4pt;vertical-align:top;width:56.35pt;\"><p style=\"text-align:center;\">&nbsp;</p></td><td style=\"border-bottom:1.0pt solid black;border-left-style:none;border-right:1.0pt solid black;border-top-style:none;padding:0in 5.4pt;vertical-align:top;width:62.05pt;\"><p style=\"text-align:center;\">&nbsp;</p></td><td style=\"border-bottom:1.0pt solid black;border-left-style:none;border-right:1.0pt solid black;border-top-style:none;padding:0in 5.4pt;vertical-align:top;width:80.65pt;\"><p style=\"text-align:center;\">&nbsp;</p></td><td style=\"border-bottom:1.0pt solid black;border-left-style:none;border-right:1.0pt solid black;border-top-style:none;padding:0in 5.4pt;vertical-align:top;width:123.05pt;\"><p style=\"text-align:center;\">&nbsp;</p></td></tr></tbody></table></figure><p style=\"text-align:right;\">&nbsp;</p><p><span class=\"text-big\">हकवालाहरुको विवरण:</span></p><p><span class=\"text-big\">१. .........................………………………………….. &nbsp;ना.प्र.नं. :</span></p><p><span class=\"text-big\">2. ........................…………………………………… &nbsp;ना.प्र.नं. :</span></p><p><span class=\"text-big\">3. .........................………………………………….. &nbsp;ना.प्र.नं. :</span></p><p style=\"text-align:right;\"><span class=\"text-big\">……………………………………………………</span></p><p style=\"text-align:right;\"><span class=\"text-big\">वडा अध्यक्ष</span></p>',
        1, '2023-02-14 10:36:44', '2023-02-14 10:37:36', NULL);
